const fs = require('fs');
const env = {};
fs.readFileSync('.env.test','utf8').split(/\n/).forEach(line=>{
  line=line.trim();
  if(!line||line.startsWith('#')) return;
  const idx=line.indexOf('=');
  if(idx===-1) return;
  const key=line.slice(0,idx);
  const val=line.slice(idx+1);
  env[key]=val;
});
fs.writeFileSync('env.json', JSON.stringify(env));
